/**
 * Prefix index over Unicode strings.
 *
 * Built as a real trie: one node per distinct prefix, walked by Unicode code
 * point so characters outside the basic multilingual plane are single steps
 * rather than surrogate-pair halves. Every node keeps a count of the stored
 * words below it so prefix counts are O(prefix length) rather than a walk of
 * the subtree.
 */

/**
 * A single trie node.
 */
class TrieNode {
  /** @type {Map<string, TrieNode>} */
  children = new Map();

  /** Number of stored words in the subtree rooted at this node (this node included). */
  count = 0;

  /** Whether a word ends at this node. */
  hasValue = false;

  /** @type {unknown} */
  value = undefined;
}

/**
 * Validates that a value is a string, throwing otherwise.
 * @param {unknown} value Value to check.
 * @param {string} name Argument name to mention in the error.
 * @returns {void}
 */
function checkString(value, name) {
  if (typeof value !== 'string') {
    throw new TypeError(`${name} must be a string`);
  }
}

/**
 * Validates a search limit, throwing when it is not Infinity or a
 * non-negative safe integer.
 * @param {unknown} limit Value to check.
 * @returns {void}
 */
function checkLimit(limit) {
  const ok = limit === Number.POSITIVE_INFINITY || (Number.isSafeInteger(limit) && limit >= 0);
  if (!ok) {
    throw new TypeError('limit must be a non-negative integer');
  }
}

/**
 * Splits a string into an array of its Unicode code points.
 * @param {string} value String to split.
 * @returns {string[]} Code points, each a single string.
 */
function codePoints(value) {
  return [...value];
}

export class Trie {
  /** @type {TrieNode} */
  #root = new TrieNode();

  /** @type {number} */
  #size = 0;

  /** @type {number} */
  #nodeCount = 1;

  /** @returns {number} Number of stored words. */
  get size() {
    return this.#size;
  }

  /** @returns {number} Number of nodes, the root included. */
  get nodeCount() {
    return this.#nodeCount;
  }

  /**
   * Stores a value under a word, replacing any value already there.
   * @param {string} word Word to store.
   * @param {unknown} value Value to associate.
   * @returns {unknown} Previously stored value, or undefined when the word is new.
   */
  insert(word, value) {
    checkString(word, 'word');
    const chars = codePoints(word);
    let node = this.#root;
    for (const ch of chars) {
      let child = node.children.get(ch);
      if (!child) {
        child = new TrieNode();
        node.children.set(ch, child);
        this.#nodeCount += 1;
      }
      node = child;
    }
    const isNew = !node.hasValue;
    const previous = node.hasValue ? node.value : undefined;
    node.hasValue = true;
    node.value = value;
    if (isNew) {
      this.#size += 1;
      let n = this.#root;
      n.count += 1;
      for (const ch of chars) {
        n = n.children.get(ch);
        n.count += 1;
      }
    }
    return previous;
  }

  /**
   * Walks to the node for a word, returning undefined when the path is missing.
   * @param {string} word Word to walk to.
   * @returns {TrieNode | undefined} Node at the end of the word, if present.
   */
  #walk(word) {
    let node = this.#root;
    for (const ch of codePoints(word)) {
      const child = node.children.get(ch);
      if (!child) return undefined;
      node = child;
    }
    return node;
  }

  /**
   * Reads the value stored under a word.
   * @param {string} word Word to look up.
   * @returns {unknown} Stored value, or undefined when the word is absent.
   */
  get(word) {
    checkString(word, 'word');
    const node = this.#walk(word);
    return node && node.hasValue ? node.value : undefined;
  }

  /**
   * Reports whether a word is stored.
   * @param {string} word Word to look up.
   * @returns {boolean} True when the word is stored.
   */
  has(word) {
    checkString(word, 'word');
    const node = this.#walk(word);
    return Boolean(node && node.hasValue);
  }

  /**
   * Removes a word and any nodes it alone kept alive.
   * @param {string} word Word to remove.
   * @returns {boolean} True when a word was removed.
   */
  delete(word) {
    checkString(word, 'word');
    const chars = codePoints(word);
    const path = [this.#root];
    let node = this.#root;
    for (const ch of chars) {
      const child = node.children.get(ch);
      if (!child) return false;
      path.push(child);
      node = child;
    }
    if (!node.hasValue) return false;
    node.hasValue = false;
    node.value = undefined;
    this.#size -= 1;
    for (const n of path) {
      n.count -= 1;
    }
    for (let i = path.length - 1; i > 0; i -= 1) {
      const n = path[i];
      if (n.count === 0) {
        const parent = path[i - 1];
        parent.children.delete(chars[i - 1]);
        this.#nodeCount -= 1;
      } else {
        break;
      }
    }
    return true;
  }

  /**
   * Counts the stored words that start with a prefix.
   * @param {string} prefix Prefix to count under.
   * @returns {number} Number of words with that prefix.
   */
  countPrefix(prefix) {
    checkString(prefix, 'prefix');
    const node = this.#walk(prefix);
    return node ? node.count : 0;
  }

  /**
   * Collects words in code point order under a node, up to a limit.
   * @param {TrieNode} node Node to start from.
   * @param {string} prefix Word accumulated so far.
   * @param {number} limit Maximum entries to collect.
   * @param {Array<[string, unknown]>} out Accumulator of [word, value] pairs.
   * @returns {void}
   */
  #collect(node, prefix, limit, out) {
    if (out.length >= limit) return;
    if (node.hasValue) {
      out.push([prefix, node.value]);
      if (out.length >= limit) return;
    }
    const keys = [...node.children.keys()].sort(
      (a, b) => a.codePointAt(0) - b.codePointAt(0),
    );
    for (const key of keys) {
      this.#collect(node.children.get(key), prefix + key, limit, out);
      if (out.length >= limit) return;
    }
  }

  /**
   * Lists the stored words that start with a prefix, in code point order.
   * @param {string} prefix Prefix to search under.
   * @param {number} [limit] Maximum number of words to return.
   * @returns {string[]} Matching words.
   */
  search(prefix, limit = Number.POSITIVE_INFINITY) {
    checkString(prefix, 'prefix');
    checkLimit(limit);
    const node = this.#walk(prefix);
    if (!node || limit === 0) return [];
    const out = [];
    this.#collect(node, prefix, limit, out);
    return out.map(([word]) => word);
  }

  /**
   * Lists every stored word with its value, in code point order.
   * @returns {Array<[string, unknown]>} Word and value pairs.
   */
  entries() {
    const out = [];
    this.#collect(this.#root, '', Number.POSITIVE_INFINITY, out);
    return out;
  }

  /**
   * Finds the longest stored word that is a prefix of the text.
   * @param {string} text Text to match against.
   * @returns {{word: string, value: unknown} | null} Longest match, or null.
   */
  longestPrefixMatch(text) {
    checkString(text, 'text');
    let node = this.#root;
    let best = null;
    let word = '';
    if (node.hasValue) best = { word: '', value: node.value };
    for (const ch of codePoints(text)) {
      const child = node.children.get(ch);
      if (!child) break;
      node = child;
      word += ch;
      if (node.hasValue) best = { word, value: node.value };
    }
    return best;
  }
}

